<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');} $nombre=trim((string)($_POST['nombre']??'')); $eslogan=trim((string)($_POST['eslogan']??'')); $telefono=trim((string)($_POST['telefono_whatsapp']??'')); $direccion=trim((string)($_POST['direccion']??'')); $ciudad=trim((string)($_POST['ciudad']??'Cusco')); $modalidad=(string)($_POST['modalidad']??'alquilada_fija'); $comision=(float)($_POST['porcentaje_comision']??0); $valid=['alquilada_fija','alquilada_comision','administrada']; if($nombre===''||$telefono===''||!in_array($modalidad,$valid,true)||$comision<0||$comision>100){http_response_code(400);exit('Completa correctamente los datos de la tienda.');} $slug=trim((string)preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$nombre))),'-'); if($slug==='')$slug='tienda'; $config=require __DIR__.'/config.php'; try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$base=$slug;$n=2;while(true){try{$q=$pdo->prepare('INSERT INTO tiendas (nombre,slug,eslogan,telefono_whatsapp,direccion,ciudad,modalidad,porcentaje_comision) VALUES (?,?,?,?,?,?,?,?)');$q->execute([$nombre,$slug,$eslogan,$telefono,$direccion,$ciudad,$modalidad,number_format($comision,2,'.','')]);break;}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$slug=$base.'-'.$n++;}} header('Location: tiendas-admin.php?created=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo registrar la tienda.');}
